uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float speed;
uniform float density;
uniform float slant;
float hash(float2 p){return fract(sin(dot(p,float2(127.1,311.7)))*43758.5453);}half4 main(float2 coord){half4 c=image.eval(coord);float x=floor(coord.x/size.x*density);float y=fract(coord.y/size.y+time*speed+hash(float2(x,1.0)));float rail=abs(fract((coord.x+slant*coord.y)/max(size.x,1.0)*density)-0.5);float m=step(0.48, y)*step(0.47,rail)*amount;return half4(clamp(c.rgb+half(m)*c.a,half3(0),half3(1)),c.a);}
